import React, { useState, useEffect, useRef, useCallback } from 'react';
import './Ring.css';

const Ring = ({
  timeLeft,
  targetTime,
  isRunning,
  onStart,
  onStop,
  onReset,
  onTimeClick,
  activeColor = '#ff3b30',
  restColor = '#007aff',
  flickering = false,
  restTime = 15,
  isPrepPhase = false,
  isPostPrepRest = false,
  activeLastMinute = true,
  isRestExercise = false,
  drawIn = false,
  revealTime = false,
  isCompleted = false,
  setCount = 1,
  onNextSet
}) => {
  const [drawInPhase, setDrawInPhase] = useState(drawIn ? 'title' : 'done');
  // Flicker: alternate between active/rest colors rapidly
  const [flickerToggle, setFlickerToggle] = useState(false);
  const flickerRef = useRef(null);

  // Parent says auth is ready — start the fadeout/reveal immediately
  useEffect(() => {
    if (!revealTime || drawInPhase !== 'title') return;
    setDrawInPhase('fadeout');
    const timer = setTimeout(() => setDrawInPhase('time'), 300);
    const doneTimer = setTimeout(() => setDrawInPhase('done'), 800);
    return () => { clearTimeout(timer); clearTimeout(doneTimer); };
  }, [revealTime]);

  useEffect(() => {
    if (flickering) {
      flickerRef.current = setInterval(() => {
        setFlickerToggle(prev => !prev);
      }, 250);
    } else {
      if (flickerRef.current) clearInterval(flickerRef.current);
      setFlickerToggle(false);
    }
    return () => { if (flickerRef.current) clearInterval(flickerRef.current); };
  }, [flickering]);

  const progress = ((targetTime - timeLeft) / targetTime) * 100;
  const circumference = 2 * Math.PI * 120;
  const strokeDasharray = circumference;
  const strokeDashoffset = circumference - (progress / 100) * circumference;

  // Determine progress color based on seconds within current minute
  const getProgressColor = () => {
    if (!isRunning && timeLeft > 0) {
      return '#ffffff';
    }
    if (flickering) {
      return flickerToggle ? restColor : activeColor;
    }
    // Prep phase + first rest period after prep — always rest color
    if (isPrepPhase || isPostPrepRest) {
      return restColor;
    }
    const currentSeconds = timeLeft % 60;
    // Rest exercise — always show rest color (entire minute is inactive)
    if (isRestExercise) {
      return restColor;
    }
    // Rest seconds at the start of each minute (except the last minute)
    if (currentSeconds >= 1 && currentSeconds <= restTime && (activeLastMinute ? timeLeft > 60 : true)) {
      return restColor;
    } else {
      return activeColor;
    }
  };

  // Helper to convert hex to rgba for glow filter
  const hexToRgba = (hex, alpha) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  };

  const formatTime = (seconds) => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins.toString().padStart(2, '0')}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="timer-display">
      <svg className="progress-ring" width="300" height="300">
        <circle
          className={`progress-ring-bg ${drawIn ? 'draw-in' : ''}`}
          stroke="rgba(44, 44, 46, 0.93)"
          strokeWidth="8"
          fill="transparent"
          r="120"
          cx="150"
          cy="150"
        />
        <circle
          className={`progress-ring-fill ${drawInPhase !== 'done' ? 'draw-in-hidden' : ''}`}
          stroke={getProgressColor()}
          strokeWidth="8"
          fill="transparent"
          r="120"
          cx="150"
          cy="150"
          strokeDasharray={strokeDasharray}
          strokeDashoffset={drawInPhase !== 'done' ? circumference : strokeDashoffset}
          strokeLinecap="round"
          transform="rotate(-90 150 150)"
          style={{ filter: getProgressColor() === '#ffffff'
            ? `drop-shadow(0 0 6px ${hexToRgba(getProgressColor(), 0.3)}) drop-shadow(0 0 14px ${hexToRgba(getProgressColor(), 0.15)})`
            : `drop-shadow(0 0 8px ${hexToRgba(getProgressColor(), 0.7)}) drop-shadow(0 0 20px ${hexToRgba(getProgressColor(), 0.5)}) drop-shadow(0 0 40px ${hexToRgba(getProgressColor(), 0.25)})` }}
        />
      </svg>

      {drawIn && (drawInPhase === 'title' || drawInPhase === 'fadeout') && (
        <div className="ring-brand-title">
          {'HIITem'.split('').map((char, i) => (
            <span key={i} className={drawInPhase === 'fadeout' ? 'brand-letter-out' : 'brand-letter'} style={drawInPhase === 'fadeout' ? { animationDelay: `${i * 60}ms` } : undefined}>{char}</span>
          ))}
        </div>
      )}
      {!(drawIn && drawInPhase === 'title') && (
        <div
          className={`time-text ${drawIn && (drawInPhase === 'fadeout' || drawInPhase === 'time') ? 'draw-in-time' : ''}`}
          onClick={onTimeClick}
          style={{ cursor: 'pointer' }}
        >
          {drawIn && drawInPhase === 'fadeout'
            ? formatTime(timeLeft).split('').map((char, i) => (
                <span key={i} className="digit-stagger" style={{ animationDelay: `${i * 60}ms` }}>{char}</span>
              ))
            : (() => { const t = formatTime(timeLeft); const colonIdx = t.indexOf(':'); return <>{t.slice(0, colonIdx + 1)}<span className="time-seconds">{t.slice(colonIdx + 1)}</span></>; })()
          }
        </div>
      )}

      {!(drawIn && drawInPhase === 'title') && (
        <button
          className={`play-btn ${isRunning ? 'hidden' : ''} ${drawIn && (drawInPhase === 'fadeout' || drawInPhase === 'time') ? 'draw-in-time' : ''}`}
          onClick={isCompleted ? onNextSet : onStart}
        >
          {isCompleted ? (
            <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" style={{ filter: 'drop-shadow(0 0 4px currentColor)' }}>
              <polyline points="1 4 1 10 7 10"/>
              <path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
            </svg>
          ) : (
            <svg width="18" height="18" viewBox="0 0 24 24" fill="currentColor" style={{ marginLeft: '1px', filter: 'drop-shadow(0 0 4px currentColor)' }}>
              <path d="M7.5 4.5c0-1.08 1.22-1.71 2.1-1.08l10.2 7.5c.76.56.76 1.6 0 2.16l-10.2 7.5c-.88.63-2.1 0-2.1-1.08V4.5z"/>
            </svg>
          )}
        </button>
      )}

      <button className={`reset-btn ${!isRunning && timeLeft < targetTime && !isCompleted && drawInPhase === 'done' ? '' : 'hidden'}`} onClick={onReset}>
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <polyline points="1 4 1 10 7 10"/>
          <path d="M3.51 15a9 9 0 1 0 2.13-9.36L1 10"/>
        </svg>
      </button>

      <button className={`pause-btn ${isRunning ? '' : 'hidden'}`} onClick={onStop}>
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none">
          <rect x="6" y="4" width="4" height="16" fill="currentColor"/>
          <rect x="14" y="4" width="4" height="16" fill="currentColor"/>
        </svg>
      </button>
    </div>
  );
};

export default Ring;
